use std::cmp::Reverse;
use std::collections::{BinaryHeap,VecDeque};
pub fn bfs(graph:&[Vec<usize>],start:usize)->Vec<usize>{let mut seen=vec![false;graph.len()];let mut q=VecDeque::new();let mut o=Vec::new();if start>=graph.len(){return o}seen[start]=true;q.push_back(start);while let Some(v)=q.pop_front(){o.push(v);for &n in &graph[v]{if n<graph.len()&&!seen[n]{seen[n]=true;q.push_back(n)}}}o}
pub fn dfs(graph:&[Vec<usize>],start:usize)->Vec<usize>{fn go(g:&[Vec<usize>],v:usize,s:&mut[bool],o:&mut Vec<usize>){if v>=g.len()||s[v]{return}s[v]=true;o.push(v);for &n in &g[v]{go(g,n,s,o)}}let mut s=vec![false;graph.len()];let mut o=Vec::new();go(graph,start,&mut s,&mut o);o}
pub fn dijkstra(graph:&[Vec<(usize,u64)>],start:usize)->Vec<u64>{let inf=u64::MAX/4;let mut d=vec![inf;graph.len()];if start>=graph.len(){return d}let mut q=BinaryHeap::new();d[start]=0;q.push((Reverse(0u64),start));while let Some((Reverse(cost),v))=q.pop(){if cost!=d[v]{continue}for&(n,w)in&graph[v]{let nc=cost.saturating_add(w);if n<d.len()&&nc<d[n]{d[n]=nc;q.push((Reverse(nc),n))}}}d}
pub fn topological_sort(graph:&[Vec<usize>])->Option<Vec<usize>>{let mut indeg=vec![0;graph.len()];for e in graph{for &v in e{if v>=graph.len(){return None}indeg[v]+=1}}let mut q=VecDeque::new();for(i,&d)in indeg.iter().enumerate(){if d==0{q.push_back(i)}}let mut o=Vec::new();while let Some(v)=q.pop_front(){o.push(v);for &n in &graph[v]{indeg[n]-=1;if indeg[n]==0{q.push_back(n)}}}if o.len()==graph.len(){Some(o)}else{None}}
pub fn connected_components(graph:&[Vec<usize>])->Vec<Vec<usize>>{let mut seen=vec![false;graph.len()];let mut out=Vec::new();for s in 0..graph.len(){if seen[s]{continue}let mut c=Vec::new();let mut q=VecDeque::from([s]);seen[s]=true;while let Some(v)=q.pop_front(){c.push(v);for &n in &graph[v]{if n<graph.len()&&!seen[n]{seen[n]=true;q.push_back(n)}}}out.push(c)}out}
